#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    /* No arguments (except program name) */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse the first argument – the value of x */
    char *endptr;
    long long x = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0') {               /* not a pure integer */
        puts("BAD_INPUT");
        return 0;
    }

    /* Use the absolute value of x (the original program treats a negative
       x as its absolute value) */
    if (x < 0)
        x = -x;

    /* x must be in the range [0,10] */
    if (x > 10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* If only x is supplied, the polynomial is empty */
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }

    /* Too many arguments – the original program only supports up to 12
       coefficients (i.e. at most 14 arguments total) */
    if (argc > 14) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Parse the coefficients (argv[2] … argv[argc‑1]) */
    int coeff_cnt = argc - 2;                 /* number of coefficients */
    long long coeff[12];                      /* maximum 12 coefficients */

    for (int i = 0; i < coeff_cnt; ++i) {
        char *e;
        long long v = strtoll(argv[i + 2], &e, 10);
        if (*e != '\0') {                     /* malformed coefficient */
            puts("BAD_INPUT");
            return 0;
        }
        coeff[i] = v;
    }

    /* Horner's method – evaluate the polynomial */
    long long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeff[i];
    }

    printf("%lld\n", result);
    return 0;
}
}
